ns16:scriptTask.ns16:script:
tw.local.odcRequest.submitToHub = false;
if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.submitRequest){
	tw.local.odcRequest.appInfo.status   ="" + tw.epv.Status.initiated;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.pendingComplianceRepInitiationReview;
	
	tw.local.lastAction=  tw.epv.CreationActions.submitRequest;
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.submitRequestToHubDirectly){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.PendingExecutionHubProcessing;
	tw.local.odcRequest.submitToHub = true;
	tw.local.lastAction = tw.epv.CreationActions.submitRequestToHubDirectly;
	tw.local.odcRequest.ReversalReason.executionHub.value = tw.local.hubCode;
	tw.local.odcRequest.ReversalReason.executionHub.name = tw.local.hubName;
}
else{
	tw.local.odcRequest.appInfo.status    ="" + tw.epv.Status.Canceled;
	tw.local.odcRequest.appInfo.subStatus ="" + tw.epv.Status.Canceled;
	tw.local.lastAction                   =tw.epv.CreationActions.cancelRequest;
}

 tw.local.odcRequest.BasicDetails.requestNature = tw.local.odcRequest.requestNature.value;
 tw.local.odcRequest.BasicDetails.requestType = tw.local.odcRequest.requestType.value;
 tw.local.odcRequest.BasicDetails.parentRequestNo = tw.local.odcRequest.parentRequestNo;

 
if(tw.local.isFirstTime == false)
{
tw.local.odcRequest.stepLog ={};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step = "" + tw.epv.ScreenNames.closureACT01;

tw.local.actionConditions = {};
tw.local.actionConditions.complianceApproval= false;
tw.local.actionConditions.screenName= tw.epv.ScreenNames.closureACT01;
//
	tw.local.odcRequest.appInfo.stepName = tw.epv.ScreenNames.closureACT01;
	//tw.local.odcRequest.appInfo.instanceID = tw.system.processInstance.id;
	if(tw.local.routingDetails.branchCode != "" && tw.local.routingDetails.branchCode != null)
	{
		tw.local.role = tw.epv.userRole.branch;
	}
	else
	{
		tw.local.role = tw.epv.userRole.hub;
	}

}

else
{
	var date = new Date();
	tw.local.odcRequest.appInfo.requestDate =  date.getDate()+'/' +(date.getMonth() + 1) + '/' + date.getFullYear();
	
	tw.local.odcRequest.appInfo.initiator = tw.system.user.fullName+"( "+ tw.system.user.name+")";
//	tw.local.odcRequest.appInfo.requestName = "ODC Closure";
	tw.local.odcRequest.appInfo.requestName = tw.epv.ProcessNames.odcClosure;

	tw.local.odcRequest.appInfo.status ="Initiated";
	tw.local.odcRequest.appInfo.subStatus ="Initiated";
	tw.local.odcRequest.appInfo.stepName = tw.epv.ScreenNames.closureACT01;
	tw.local.odcRequest.appInfo.instanceID =tw.local.odcRequest.requestNo;
	if(tw.local.routingDetails.branchCode != "" && tw.local.routingDetails.branchCode != null)
	{
		tw.local.role = tw.epv.userRole.branch;
		tw.local.odcRequest.InitiatorHubBranch = "Branch: "+tw.local.routingDetails.branchName;
	}
	else
	{
		tw.local.role = tw.epv.userRole.hub;
			tw.local.odcRequest.InitiatorHubBranch = "Hub: "+tw.local.routingDetails.hubName;
	}
	tw.local.odcRequest.BasicDetails.requestState = "Undergoing closure";
	
	tw.local.odcRequest.stepLog ={};
	tw.local.odcRequest.stepLog.startTime = new Date();
	tw.local.odcRequest.stepLog.step = tw.epv.ScreenNames.closureACT01;//"Create ODC Closure Request – انشاء طلب اقفال تحصيل مستندى تصدير ";
	
	tw.local.actionConditions = {};
	tw.local.actionConditions.complianceApproval= false;
	tw.local.actionConditions.screenName= tw.epv.ScreenNames.closureACT01;
}	

tw.local.initiator = tw.system.user.name;
tw.local.odcRequest.instanceNo = tw.system.processInstance.id;

 tw.local.errorMessage ="";
 var mandatoryTriggered = false;
 
/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.cancelRequest)
{	mandatory(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment");
	maxLength(tw.local.odcRequest.stepLog.comment , "tw.local.odcRequest.stepLog.comment", 500 , "Shouldn't be more than 500 character" , "Comment: " + "Shouldn't be more than 500 character" );	
}else{
	mandatory(tw.local.odcRequest.ReversalReason.closureReason, "tw.local.odcRequest.ReversalReason.closureReason");
	maxLength(tw.local.odcRequest.ReversalReason.closureReason , "tw.local.odcRequest.ReversalReason.closureReason", 160 , "Shouldn't be more than 160 character" , "Closure Reason: " + "Shouldn't be more than 160 character" );
}
	

function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{			
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
	
			default:
				
				// VALIDATE DATE OBJECT
				if( field && field.getTime && isFinite(field.getTime()) ) {}
				
				else
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;	
				}
		}
	}
	return true;
}

function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}
function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}

 tw.local.errorMessage ="";

ns16:extensionElements.ns2:preAssignmentScript:
if (tw.local.hubCode!= null && tw.local.hubCode != "" && tw.local.crMaker == true) {
	tw.local.TEAM_NAME = tw.epv.TeamsNameBPM.HUB_CR_MKR+"";
	tw.local.TEAM_MANAGER = tw.epv.TeamsNameBPM.HUB_CR_MKR_Manager+"";
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.idc_hub_cr;
}
else if (tw.local.hubCode!= null && tw.local.hubCode != "" && tw.local.crMaker == false){
	tw.local.TEAM_NAME = tw.epv.TeamsNameBPM.HUB_EXE_MKR+"";
	tw.local.TEAM_MANAGER = tw.epv.TeamsNameBPM.HUB_EXE_Manager+"";
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.idc_hub_exe_Maker;
}
else{
	tw.local.TEAM_NAME = tw.epv.TeamsNameBPM.Branches_Operation_Makers+"";
	tw.local.TEAM_MANAGER = tw.epv.TeamsNameBPM.BranchMakerManager+"";
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.Branch_Opereration_Maker;
}

tw.local.TASK_ID = tw.system.processInstance.task.id;
tw.local.OWNER_ID = tw.system.user.id;

